-- PROPOSED ONLY; follows proposed 009. Never applied by the approved eight-migration runner.
-- Additive schema only. No existing role assignments, data, ownership constraints or columns replaced.
INSERT INTO ab.permissions(id) SELECT unnest(ARRAY['customer_view','customer_create','customer_edit','customer_status','customer_transfer','customer_export','customer_print','customer_documents','customer_relations','customer_followup','customer_review','customer_audit','customer_notify','customer_configure','customer_import','customer_undertaking_issue','customer_undertaking_edit','customer_undertaking_cancel','customer_undertaking_complete']) ON CONFLICT DO NOTHING;
CREATE TABLE ab.customer_numbers(tenant_id uuid PRIMARY KEY REFERENCES ab.organizations,next_number bigint NOT NULL DEFAULT 1 CHECK(next_number>0));
CREATE TABLE ab.customers(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,file_number bigint NOT NULL CHECK(file_number>0),type text NOT NULL CHECK(type IN('owner','owner_driver','driver')),status text NOT NULL CHECK(status IN('Prospect','Active','Suspended','Ended','Archived')),payload_cipher text NOT NULL,search_tokens text[] NOT NULL DEFAULT '{}',official_keys text[] NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,file_number),FOREIGN KEY(tenant_id,company_id) REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES ab.users(tenant_id,id));
CREATE INDEX customer_order ON ab.customers(tenant_id,company_id,file_number);
CREATE INDEX customer_search ON ab.customers USING gin(search_tokens);
CREATE INDEX customer_official ON ab.customers USING gin(official_keys);
CREATE TABLE ab.customer_drafts(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,actor_id uuid NOT NULL,company_id uuid NOT NULL,payload_cipher text NOT NULL,revision integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),final_customer_id uuid,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES ab.users(tenant_id,id),FOREIGN KEY(tenant_id,company_id) REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,final_customer_id) REFERENCES ab.customers(tenant_id,id));
CREATE TABLE ab.customer_events(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,customer_id uuid NOT NULL,company_id uuid NOT NULL,actor_id uuid NOT NULL,kind text NOT NULL,source_key text NOT NULL,payload_cipher text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,source_key),FOREIGN KEY(tenant_id,customer_id) REFERENCES ab.customers(tenant_id,id),FOREIGN KEY(tenant_id,company_id) REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES ab.users(tenant_id,id));
CREATE INDEX customer_timeline ON ab.customer_events(tenant_id,customer_id,created_at);
CREATE TABLE ab.customer_visits(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,actor_id uuid NOT NULL,payload_cipher text NOT NULL,occurred_at timestamptz NOT NULL,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,company_id) REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.customer_visit_people(tenant_id uuid NOT NULL,visit_id uuid NOT NULL,customer_id uuid NOT NULL,PRIMARY KEY(tenant_id,visit_id,customer_id),FOREIGN KEY(tenant_id,visit_id) REFERENCES ab.customer_visits(tenant_id,id),FOREIGN KEY(tenant_id,customer_id) REFERENCES ab.customers(tenant_id,id));
CREATE TABLE ab.customer_files(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,customer_id uuid NOT NULL,company_id uuid NOT NULL,parent_id uuid,version integer NOT NULL CHECK(version>0),storage_key text NOT NULL UNIQUE,digest text NOT NULL,payload_cipher text NOT NULL,size integer NOT NULL CHECK(size BETWEEN 1 AND 10485760),mime text NOT NULL CHECK(mime IN('application/pdf','image/png','image/jpeg','image/webp')),scan_status text NOT NULL CHECK(scan_status IN('pending','clean','rejected')),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,customer_id) REFERENCES ab.customers(tenant_id,id),FOREIGN KEY(tenant_id,company_id) REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,parent_id) REFERENCES ab.customer_files(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES ab.users(tenant_id,id));
CREATE UNIQUE INDEX customer_file_version_chain ON ab.customer_files(tenant_id,parent_id) WHERE parent_id IS NOT NULL;
CREATE TABLE ab.customer_templates(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,template_key uuid NOT NULL,version integer NOT NULL,company_id uuid NOT NULL,payload_cipher text NOT NULL,action text NOT NULL CHECK(action IN('issue','edit','cancel')),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,template_key,version),FOREIGN KEY(tenant_id,company_id) REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.customer_imports(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,actor_id uuid NOT NULL,source_hash text NOT NULL,payload_cipher text NOT NULL,cursor integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'Preview' CHECK(status IN('Preview','Running','Completed')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,actor_id,source_hash),FOREIGN KEY(tenant_id,company_id) REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES ab.users(tenant_id,id));
ALTER TABLE ab.finance_notifications ADD COLUMN due_at timestamptz NOT NULL DEFAULT now();
CREATE INDEX central_notification_due ON ab.finance_notifications(tenant_id,user_id,due_at);
DO $$ DECLARE tab text; BEGIN FOREACH tab IN ARRAY ARRAY['customers','customer_numbers','customer_drafts','customer_events','customer_visits','customer_visit_people','customer_files','customer_templates','customer_imports'] LOOP
 EXECUTE format('ALTER TABLE ab.%I ENABLE ROW LEVEL SECURITY',tab);
 EXECUTE format('CREATE POLICY tenant_scope ON ab.%I USING(tenant_id=ab.tenant()) WITH CHECK(tenant_id=ab.tenant())',tab);
 EXECUTE format('GRANT SELECT,INSERT ON ab.%I TO ab_runtime',tab);
 END LOOP; END $$;
GRANT UPDATE ON ab.customers,ab.customer_numbers,ab.customer_drafts,ab.customer_imports TO ab_runtime;
CREATE FUNCTION ab.customer_history_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable customer history' USING ERRCODE='23514'; END $$;
CREATE TRIGGER customer_events_immutable BEFORE UPDATE OR DELETE ON ab.customer_events FOR EACH ROW EXECUTE FUNCTION ab.customer_history_immutable();
CREATE TRIGGER customer_files_immutable BEFORE UPDATE OR DELETE ON ab.customer_files FOR EACH ROW EXECUTE FUNCTION ab.customer_history_immutable();
CREATE TRIGGER customer_templates_immutable BEFORE UPDATE OR DELETE ON ab.customer_templates FOR EACH ROW EXECUTE FUNCTION ab.customer_history_immutable();
REVOKE ALL ON FUNCTION ab.customer_history_immutable() FROM PUBLIC;
-- Scanner uses the existing restricted worker role; file metadata remains immutable.
CREATE TABLE ab.customer_file_reviews(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,file_id uuid NOT NULL,verdict text NOT NULL CHECK(verdict IN('clean','rejected')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,file_id),FOREIGN KEY(tenant_id,file_id) REFERENCES ab.customer_files(tenant_id,id));
ALTER TABLE ab.customer_file_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON ab.customer_file_reviews USING(tenant_id=ab.tenant()) WITH CHECK(tenant_id=ab.tenant());
GRANT SELECT ON ab.customer_file_reviews TO ab_runtime;
CREATE FUNCTION ab.pending_customer_files() RETURNS TABLE(id uuid,storage_key text,mime text,sha256 text) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,ab AS $$ SELECT f.id,f.storage_key,f.mime,f.digest FROM ab.customer_files f WHERE f.scan_status='pending' AND NOT EXISTS(SELECT 1 FROM ab.customer_file_reviews r WHERE r.file_id=f.id) ORDER BY f.created_at LIMIT 20 $$;
CREATE FUNCTION ab.record_customer_scan(target uuid,result text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ab AS $$ DECLARE org uuid; BEGIN IF result NOT IN('clean','rejected') THEN RAISE EXCEPTION 'invalid scan result'; END IF; SELECT tenant_id INTO org FROM ab.customer_files WHERE id=target AND scan_status='pending'; IF org IS NOT NULL THEN INSERT INTO ab.customer_file_reviews VALUES(gen_random_uuid(),org,target,result,now()) ON CONFLICT(tenant_id,file_id)DO NOTHING; INSERT INTO ab.audit_events(id,tenant_id,actor_id,actor_type,action,entity_type,entity_id,fields,request_id) VALUES(gen_random_uuid(),org,'00000000-0000-4000-8000-000000000001','service','customer_file_scanned','customer_file',target,ARRAY['scan_status',result],gen_random_uuid()); END IF; END $$;
REVOKE ALL ON FUNCTION ab.pending_customer_files(),ab.record_customer_scan(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ab.pending_customer_files(),ab.record_customer_scan(uuid,text) TO ab_scanner;
